          ],
          "Security Objectives": [
            "I"
          ],
          "Secondary To": [],
          "Functionality": "Stores the writable system-information array, including the word initialized from CLOCK_FREQUENCY and overwritten by a qualifying bus write.",
          "Justification": "It is the internal element that directly holds the conceptual value at lines 92 and 95.",
          "Asset Lines": [
            92,
            95
          ]
        },
        {
