            }
          ],
          "Functionality": "Decides whether the bus request is a write capable of assigning the primary system-information word.",
          "Justification": "It is a condition of the assignment to sysinfo at line 94 and can gate the integrity-changing write.",
          "Asset Lines": [
            94
          ]
        },
